mapper.select:
select sup.id, sup.code, sup.name, sup.disabled as supplierDisabled, array_to_string(array_agg(po.id), ',') AS purchaseOrderIds, count(distinct po.id) as purchaseCount, sum(pod.purchase_qty) as purchaseQty, sum(pod.purchase_amount) as purchaseAmount from supplier sup inner join purchase_order_supplier pos on pos.supplier_id = sup.id and pos.is_deleted = false inner join purchase_order po on po.id = pos.purchase_order_id and po.is_deleted = false and po.approve_status = 'approve' inner join purchase_order_detail pod on pod.purchase_order_id = po.id and pod.is_deleted = false
sup.is_deleted = false
AND sup.name IN
#{item}
AND po.purchase_date >= #{params.dateList[0]} AND (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > po.purchase_date
${params.permissionSql}
group by sup.id order by
${item.field} ${item.sort}
purchaseAmount desc NULLS LAST

